-- Generated by setup/vmangos/pack.py from courses/courses.json (docs/courses.md): edit that
-- file and rerun pack.py. The Race Marshals of World of Kartcraft, for the world database
-- (mangos). vmangos-deploy runs it from storage/database/custom-sql/ on every database start,
-- so it replaces its own rows, and only those.

START TRANSACTION;

DELETE FROM `creature` WHERE `guid` BETWEEN 400000 AND 400999 OR `id` = 190000;
DELETE FROM `creature_template` WHERE `entry` = 190000;
DELETE FROM `npc_text` WHERE `ID` IN (190000, 190001, 190002, 190003, 190004);
DELETE FROM `broadcast_text` WHERE `entry` IN (190000, 190001, 190002, 190003, 190004);

INSERT INTO `broadcast_text` (`entry`, `male_text`, `female_text`) VALUES
(190000, 'Racers, start your engines! Every course that starts here is yours to host: pick one, gather your friends, and when the host says go, everyone lines up on the grid.', 'Racers, start your engines! Every course that starts here is yours to host: pick one, gather your friends, and when the host says go, everyone lines up on the grid.'),
(190001, 'Host a race on a course that starts here, or join one that is waiting. Anyone can join until the host starts it; then every racer is put on the grid behind the line for the countdown.$B$BPass every checkpoint in order. A circuit runs its laps back through the start; a sprint ends at its last checkpoint. Break crates along the way for Wumpa fruit and weapons.$B$BEvery finish pays experience and Karting skill, the more the better your place. Far from a start? The Race Finder queues you for any course and takes you there.$B$BA time trial is you alone against the clock: no crates, no weapons, and the ghost of your best run to chase. Its times go on their own leaderboard.$B$BThe host picks whether ground types count: with them on, grass, dirt, snow, mud and water slow every racer alike.', 'Host a race on a course that starts here, or join one that is waiting. Anyone can join until the host starts it; then every racer is put on the grid behind the line for the countdown.$B$BPass every checkpoint in order. A circuit runs its laps back through the start; a sprint ends at its last checkpoint. Break crates along the way for Wumpa fruit and weapons.$B$BEvery finish pays experience and Karting skill, the more the better your place. Far from a start? The Race Finder queues you for any course and takes you there.$B$BA time trial is you alone against the clock: no crates, no weapons, and the ghost of your best run to chase. Its times go on their own leaderboard.$B$BThe host picks whether ground types count: with them on, grass, dirt, snow, mud and water slow every racer alike.'),
(190002, 'The fastest times on the courses that start here, and the record holders. Beat one and your name goes up on the board.', 'The fastest times on the courses that start here, and the record holders. Beat one and your name goes up on the board.'),
(190003, 'The fastest time trials on the courses that start here: one racer, no weapons, only the clock. Set a time and see where you stand.', 'The fastest time trials on the courses that start here: one racer, no weapons, only the clock. Set a time and see where you stand.'),
(190004, 'Ground types on or off? On, grass, dirt, snow and mud slow every kart off the road, and water too, as they did on the old tracks; off, the whole course drives like the road. Every racer in your race drives by your choice, whatever their own settings say.', 'Ground types on or off? On, grass, dirt, snow and mud slow every kart off the road, and water too, as they did on the old tracks; off, the whole course drives like the road. Every racer in your race drives by your choice, whatever their own settings say.');

